## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/rsvPreventionLogic.ts`

```typescript
/**
 * RSV Prevention Clinical Compass™
 * Logic Engine — AAP 2024 Nirsevimab + Palivizumab Policy Statement
 *
 * References:
 * 1. AAP Committee on Infectious Diseases. Updated Guidance for Palivizumab
 *    Prophylaxis Among Infants and Young Children at Increased Risk of
 *    Hospitalization for Respiratory Syncytial Virus Infection. Pediatrics. 2014
 *    (updated 2024 with nirsevimab).
 * 2. AAP Policy Statement: Nirsevimab (Beyfortus) for RSV Prevention. Pediatrics. 2024.
 * 3. Hammitt LL et al. Nirsevimab for Prevention of RSV in Healthy Late-Preterm
 *    and Term Infants. NEJM. 2022;386:837–846. (MELODY trial)
 * 4. Griffin MP et al. Single-Dose Nirsevimab for Prevention of RSV in Preterm Infants.
 *    NEJM. 2020;383:415–425. (MEDLEY trial)
 * 5. AAP Maternal RSV Vaccine Guidance. Pediatrics. 2024.
 */

export type RSVRiskCategory =
  | "standard_risk"          // healthy term infant
  | "moderate_risk"          // preterm 29–34 weeks, CHD, CLD
  | "high_risk"              // preterm <29 weeks, severe CHD, severe CLD, immunocompromised
  | "very_high_risk";        // severe immunodeficiency, transplant

export interface RSVPreventionInput {
  ageMonths: number;
  gestationalAgeWeeks: number;
  isCurrentRSVSeason: boolean; // October–March in most US regions
  // Risk factors
  isPremature: boolean;
  hasCongenitalHeartDisease: boolean;
  chdRequiresMedication: boolean; // hemodynamically significant CHD
  hasChronicLungDisease: boolean; // BPD, CLD of prematurity
  requiresSupplementalO2: boolean;
  isImmunocompromised: boolean;
  hasDownSyndrome: boolean;
  hasCysticFibrosis: boolean;
  hasNeuromuscularDisease: boolean; // affects airway clearance
  isNativeAlaskan: boolean; // higher RSV hospitalization risk
  isInDayCare: boolean;
  hasSchoolAgeSimlings: boolean;
  // Prior prophylaxis
  receivedNirsevimabThisSeason: boolean;
  receivedPalivizumabThisSeason: boolean;
  nirsevimabDosesReceived: number;
  // Maternal vaccination
  motherReceivedRSVVaccine: boolean; // Abrysvo during pregnancy (32–36 weeks)
  motherVaccinationWeeksBeforeBirth: number | null;
  // Current status
  currentlyHospitalized: boolean;
  hasActiveRSVInfection: boolean;
}

export interface RSVPreventionRecommendation {
  primaryRecommendation: string;
  riskCategory: RSVRiskCategory;
  nirsevimabRecommendation: string;
  palivizumabRecommendation: string;
  maternalVaccinationNote: string;
  dosing: string;
  seasonalGuidance: string;
  urgentFlags: string[];
  counselingPoints: string[];
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessRSVPrevention(
  input: RSVPreventionInput
): RSVPreventionRecommendation {
  const urgentFlags: string[] = [];
  const counselingPoints: string[] = [];

  // ─── Active RSV infection ─────────────────────────────────────────────────
  if (input.hasActiveRSVInfection) {
    urgentFlags.push("ACTIVE RSV INFECTION: Nirsevimab/palivizumab are PREVENTIVE — not therapeutic. Supportive care: nasal suctioning, hydration, oxygen if SpO2 <90–92%. Hospitalize if respiratory distress, apnea, or poor feeding.");
  }

  // ─── Risk category ────────────────────────────────────────────────────────
  let riskCategory: RSVRiskCategory;
  if (input.isImmunocompromised || (input.hasCongenitalHeartDisease && input.chdRequiresMedication && input.gestationalAgeWeeks < 32)) {
    riskCategory = "very_high_risk";
  } else if (input.gestationalAgeWeeks < 29 || (input.hasCongenitalHeartDisease && input.chdRequiresMedication) || (input.hasChronicLungDisease && input.requiresSupplementalO2)) {
    riskCategory = "high_risk";
  } else if ((input.isPremature && input.gestationalAgeWeeks >= 29 && input.gestationalAgeWeeks <= 34) || input.hasCongenitalHeartDisease || input.hasChronicLungDisease || input.hasDownSyndrome || input.hasCysticFibrosis || input.hasNeuromuscularDisease) {
    riskCategory = "moderate_risk";
  } else {
    riskCategory = "standard_risk";
  }

  // ─── Nirsevimab recommendation ────────────────────────────────────────────
  let nirsevimabRec: string;
  let dosing: string;

  if (input.ageMonths > 24) {
    nirsevimabRec = "Nirsevimab not indicated for children >24 months (approved for ≤24 months entering second RSV season only if high-risk).";
    dosing = "Not applicable";
  } else if (input.receivedNirsevimabThisSeason) {
    nirsevimabRec = "Nirsevimab already received this RSV season. Single dose provides season-long protection (5 months). No additional dose needed unless entering second RSV season with high-risk condition.";
    dosing = "Already administered this season.";
  } else if (!input.isCurrentRSVSeason) {
    nirsevimabRec = "Not currently RSV season. Administer nirsevimab at the start of RSV season (October) or at birth if born during RSV season.";
    dosing = "Administer at RSV season onset.";
  } else {
    // Current RSV season + not yet received
    if (input.motherReceivedRSVVaccine && input.motherVaccinationWeeksBeforeBirth !== null && input.motherVaccinationWeeksBeforeBirth >= 2 && input.ageMonths < 6) {
      nirsevimabRec = "MATERNAL RSV VACCINE RECEIVED: Nirsevimab may be deferred for healthy term/late-preterm infants born ≥2 weeks after maternal Abrysvo vaccination (AAP 2024). Nirsevimab still recommended for high-risk infants regardless of maternal vaccination.";
    } else {
      nirsevimabRec = `NIRSEVIMAB (BEYFORTUS) RECOMMENDED: ${riskCategory === "standard_risk" ? "All infants <8 months entering first RSV season" : "High-risk infant — strongly recommended"}. Single dose provides ~5 months protection. MELODY trial: 74.5% efficacy against RSV LRTI.`;
    }

    // Dosing
    if (riskCategory === "high_risk" || riskCategory === "very_high_risk") {
      dosing = "Nirsevimab 200mg IM (≥5kg) or 100mg IM (<5kg) for high-risk infants. Standard dose: 50mg (<5kg) or 100mg (≥5kg). Note: 200mg dose for high-risk children entering second RSV season (up to 24 months).";
    } else {
      dosing = "Nirsevimab: 50mg IM if birth weight <5kg; 100mg IM if ≥5kg. Single dose. Administer before or during RSV season.";
    }
  }

  // ─── Palivizumab recommendation ───────────────────────────────────────────
  let palivizumabRec: string;
  if (riskCategory === "very_high_risk" || riskCategory === "high_risk") {
    if (input.receivedNirsevimabThisSeason) {
      palivizumabRec = "Nirsevimab received — palivizumab not needed. Nirsevimab has replaced palivizumab for most indications (AAP 2024).";
    } else {
      palivizumabRec = `PALIVIZUMAB (SYNAGIS) — ALTERNATIVE if nirsevimab unavailable: 15mg/kg IM monthly × 5 doses during RSV season. Indicated for: GA <29 weeks (≤12 months at start of season), hemodynamically significant CHD, severe CLD requiring medical therapy. Nirsevimab preferred when available.`;
    }
  } else {
    palivizumabRec = "Palivizumab not indicated for standard/moderate risk. Nirsevimab is preferred for all eligible infants.";
  }

  // ─── Maternal vaccination note ────────────────────────────────────────────
  const maternalVaccinationNote = `Maternal RSV Vaccine (Abrysvo — Pfizer): FDA-approved for pregnant women at 32–36 weeks gestation. Provides passive immunity to newborn for first ~6 months. AAP 2024: shared decision-making for maternal vaccination vs. nirsevimab. Both strategies are effective. Maternal vaccination preferred if administered ≥2 weeks before birth.`;

  // ─── Seasonal guidance ───────────────────────────────────────────────────
  const seasonalGuidance = `RSV season: typically October–March in most US regions (earlier in some southern states). Administer nirsevimab at start of RSV season or at birth if born during season. Infants born during RSV season: administer before discharge from birth hospitalization.`;

  // ─── Counseling ───────────────────────────────────────────────────────────
  counselingPoints.push(
    "RSV is the leading cause of infant hospitalization in the US — 58,000–80,000 hospitalizations/year in children <5 years.",
    "Nirsevimab (Beyfortus) is a monoclonal antibody — NOT a vaccine. It provides passive immunization for one RSV season.",
    "Hand hygiene is the most important non-pharmacologic prevention: wash hands before touching infant.",
    "Avoid exposure to sick contacts, especially during RSV season (October–March).",
    "Breastfeeding provides some protection against RSV — encourage breastfeeding.",
    "Return precautions: fast breathing, nasal flaring, retractions, poor feeding, cyanosis, apnea."
  );

  if (riskCategory === "high_risk" || riskCategory === "very_high_risk") {
    counselingPoints.push("HIGH-RISK INFANT: Avoid daycare during RSV season if possible. Limit visitors. Ensure all household contacts vaccinated against influenza.");
    urgentFlags.push(`HIGH-RISK RSV: ${riskCategory.replace("_", " ").toUpperCase()} — ensure nirsevimab administered before RSV season. Palivizumab as backup if nirsevimab unavailable.`);
  }

  const primaryRec = urgentFlags.length > 0 && !input.hasActiveRSVInfection
    ? urgentFlags[0]
    : input.hasActiveRSVInfection
    ? "ACTIVE RSV INFECTION: Supportive care. Prophylaxis not therapeutic."
    : `RSV PREVENTION — ${riskCategory.replace(/_/g, " ").toUpperCase()}. Age ${input.ageMonths} months. GA ${input.gestationalAgeWeeks} weeks. ${input.isCurrentRSVSeason ? "RSV season ACTIVE." : "Off-season."} ${input.receivedNirsevimabThisSeason ? "Nirsevimab: RECEIVED." : "Nirsevimab: NOT YET RECEIVED."}`;

  return {
    primaryRecommendation: primaryRec,
    riskCategory,
    nirsevimabRecommendation: nirsevimabRec,
    palivizumabRecommendation: palivizumabRec,
    maternalVaccinationNote,
    dosing,
    seasonalGuidance,
    urgentFlags,
    counselingPoints,
    evidenceLevel: "A",
    rationale: `Age ${input.ageMonths} months. GA ${input.gestationalAgeWeeks} weeks. Risk: ${riskCategory}. RSV season: ${input.isCurrentRSVSeason}. Nirsevimab received: ${input.receivedNirsevimabThisSeason}. Maternal RSV vaccine: ${input.motherReceivedRSVVaccine}. Per AAP 2024 nirsevimab policy.`,
    references: [
      { citation: "AAP Committee on Infectious Diseases. Nirsevimab (Beyfortus) for RSV Prevention. Pediatrics. 2024.", url: "https://publications.aap.org/pediatrics" },
      { citation: "Hammitt LL et al. Nirsevimab for Prevention of RSV in Healthy Late-Preterm and Term Infants. NEJM. 2022;386:837–846. (MELODY trial)", url: "https://www.nejm.org/doi/10.1056/NEJMoa2110275" },
      { citation: "Griffin MP et al. Single-Dose Nirsevimab for Prevention of RSV in Preterm Infants. NEJM. 2020;383:415–425. (MEDLEY trial)", url: "https://www.nejm.org/doi/10.1056/NEJMoa1913556" },
      { citation: "Kampmann B et al. Bivalent Prefusion F Vaccine in Pregnancy to Prevent RSV Illness in Infants. NEJM. 2023;388:1451–1464. (Abrysvo maternal vaccine)", url: "https://www.nejm.org/doi/10.1056/NEJMoa2216480" },
    ],
  };
}
